import os
from google.cloud import documentai_v1 as documentai
from google.cloud import translate_v3 as translate
from google.cloud import firestore
import vertexai
from vertexai.generative_models import GenerativeModel

def get_documentai_client(location: str):
    return documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{location}-documentai.googleapis.com"}
    )

def get_translation_client():
    return translate.TranslationServiceClient()

def get_firestore_client(project_id: str):
    return firestore.Client(project=project_id)

def get_vertex_ai_model(project_id: str, location: str, model_name: str = "gemini-pro"):
    vertexai.init(project=project_id, location=location)
    return GenerativeModel(model_name)

from google.cloud import documentai
from document_client import get_documentai_client
from document_models import Receipt, ReceiptItem

def extract_receipt_fields(payload: dict, config: dict = None) -> dict:
    config = config or {}
    project_id = config.get("project_id", os.environ.get("GOOGLE_CLOUD_PROJECT"))
    location = config.get("location", "us")
    processor_id = config.get("processor_id")

    if not project_id or not processor_id:
        raise ValueError("Google Cloud project_id and processor_id must be provided.")

    client = get_documentai_client(location)
    processor_name = client.processor_path(project_id, location, processor_id)

    raw_document = documentai.RawDocument(
        content=payload["document_bytes"], mime_type=payload["mime_type"]
    )
    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)
    response = client.process_document(request=request)

    receipt_fields = {
        "merchant": None,
        "total": None,
        "tax": None,
        "items": [],
        "date": None
    }

    for entity in response.document.entities:
        if entity.type_ == "line_item":
            item_values = {
                prop.type_.split("/")[-1]: prop.mention_text
                for prop in entity.properties
            }
            receipt_fields["items"].append(
                ReceiptItem(
                    description=item_values.get("description"),
                    quantity=float(item_values["quantity"]) if item_values.get("quantity") else None,
                    price=float(item_values["unit_price"]) if item_values.get("unit_price") else None,
                    amount=float(item_values["amount"]) if item_values.get("amount") else None,
                ).dict(exclude_none=True)
            )
        elif entity.type_ == "total_amount":
            receipt_fields["total"] = float(entity.mention_text) if entity.mention_text else None
        elif entity.type_ == "tax_amount":
            receipt_fields["tax"] = float(entity.mention_text) if entity.mention_text else None
        elif entity.type_ == "merchant_name":
            receipt_fields["merchant"] = entity.mention_text
        elif entity.type_ == "transaction_date":
            receipt_fields["date"] = entity.mention_text

    return {"receipts": [Receipt(**receipt_fields).dict(exclude_none=True)]}

import os
from document_models import ModerationResult
from document_client import get_vertex_ai_model
from vertexai.generative_models import HarmCategory, HarmBlockThreshold

def moderate_vendor_text(text: str, config: dict = None) -> ModerationResult:
    config = config or {}
    project_id = config.get("project_id", os.environ.get("GOOGLE_CLOUD_PROJECT"))
    location = config.get("location", "us-central1")

    if not project_id:
        raise ValueError("Google Cloud project_id must be provided.")

    model = get_vertex_ai_model(project_id, location, "gemini-1.5-flash-001")

    # The safety settings are configurable based on the desired strictness.
    # For this example, we'll set thresholds to block at a relatively low confidence.
    safety_settings = {
        HarmCategory.HARM_CATEGORY_HARASSMENT: HarmBlockThreshold.BLOCK_LOW_AND_ABOVE,
        HarmCategory.HARM_CATEGORY_HATE_SPEECH: HarmBlockThreshold.BLOCK_LOW_AND_ABOVE,
        HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT: HarmBlockThreshold.BLOCK_LOW_AND_ABOVE,
        HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT: HarmBlockThreshold.BLOCK_LOW_AND_ABOVE,
    }

    response = model.generate_content(
        [text],
        safety_settings=safety_settings
    )

    # Check if any content was blocked by safety filters
    if not response._raw_response.candidates:
        # Content was blocked, infer categories from prompt feedback
        blocked_categories = []
        for safety_rating in response._raw_response.prompt_feedback.safety_ratings:
            if safety_rating.blocked:
                blocked_categories.append(HarmCategory(safety_rating.category).name.replace('HARM_CATEGORY_', ''))
        return ModerationResult(is_safe=False, categories=blocked_categories, scores={})

    # If not blocked, extract safety attributes
    safety_attributes = response._raw_response.candidates[0].safety_ratings

    is_safe = True
    categories = []
    scores = {}

    for rating in safety_attributes:
        category_name = HarmCategory(rating.category).name.replace('HARM_CATEGORY_', '')
        scores[category_name] = rating.harm_probability # This gives a probability score
        if rating.blocked:
            is_safe = False
            categories.append(category_name)

    return ModerationResult(is_safe=is_safe, categories=categories, scores=scores)

import os
from document_models import TranslationResult
from document_client import get_translation_client

def translate_invoice_note(text: str, target_language_code: str, config: dict = None) -> TranslationResult:
    config = config or {}
    project_id = config.get("project_id", os.environ.get("GOOGLE_CLOUD_PROJECT"))

    if not project_id:
        raise ValueError("Google Cloud project_id must be provided.")

    client = get_translation_client()

    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language_code,
        }
    )

    translated_text = ""
    if response.translations:
        translated_text = response.translations[0].translated_text

    return TranslationResult(translated_text=translated_text)

import os
from document_models import NormalizedExpense
from document_client import get_firestore_client

def persist_expense_record(expense_record: NormalizedExpense, config: dict = None) -> str:
    config = config or {}
    project_id = config.get("project_id", os.environ.get("GOOGLE_CLOUD_PROJECT"))
    collection_name = config.get("collection_name", "expense_records")

    if not project_id:
        raise ValueError("Google Cloud project_id must be provided.")

    db = get_firestore_client(project_id)

    doc_ref = db.collection(collection_name).add(expense_record.dict())

    return doc_ref[1].id

def get_expense_record(record_id: str, config: dict = None) -> NormalizedExpense:
    config = config or {}
    project_id = config.get("project_id", os.environ.get("GOOGLE_CLOUD_PROJECT"))
    collection_name = config.get("collection_name", "expense_records")

    if not project_id:
        raise ValueError("Google Cloud project_id must be provided.")

    db = get_firestore_client(project_id)

    doc_ref = db.collection(collection_name).document(record_id)
    doc = doc_ref.get()

    if doc.exists:
        return NormalizedExpense(**doc.to_dict())
    else:
        raise ValueError(f"No expense record found with ID: {record_id}")

def update_expense_record(record_id: str, updates: dict, config: dict = None):
    config = config or {}
    project_id = config.get("project_id", os.environ.get("GOOGLE_CLOUD_PROJECT"))
    collection_name = config.get("collection_name", "expense_records")

    if not project_id:
        raise ValueError("Google Cloud project_id must be provided.")

    db = get_firestore_client(project_id)
    doc_ref = db.collection(collection_name).document(record_id)
    doc_ref.update(updates)


def delete_expense_record(record_id: str, config: dict = None):
    config = config or {}
    project_id = config.get("project_id", os.environ.get("GOOGLE_CLOUD_PROJECT"))
    collection_name = config.get("collection_name", "expense_records")

    if not project_id:
        raise ValueError("Google Cloud project_id must be provided.")

    db = get_firestore_client(project_id)
    db.collection(collection_name).document(record_id).delete()
